const product = (row) => ({
  id: row[1],
  store: row[0],
  name: row[2],
  category: row[3],
  price: row[4],
  popularity: row[5],
  q: row[6],
});

const dealOf = (row) =>
  Object.assign(
    {
      id: "x-" + row[1],
      store: row[0],
      label: row[7],
      category: null,
      note: row[8],
      minSpend: 0,
      percent: null,
      ends: null,
    },
    row[9] || {}
  );

export const EXTRA_PRODUCTS = ROWS.map(product);
export const EXTRA_DEALS = ROWS.map(dealOf);
